import re
html = open("08-ai-navigation-flow.html").read()

attrs = ['x1','y1','x2','y2','x','y','width','height','cx','cy']
bad_structural = []
bad_text = []
for m in re.finditer(r'<(rect|line|circle|text)\b([^>]*)>', html):
    tagname, body = m.group(1), m.group(2)
    for a in attrs:
        for v in re.findall(rf'(?<![\w-]){a}="(-?\d+(?:\.\d+)?)"', body):
            fv = float(v)
            if fv % 4 != 0:
                if tagname == 'text':
                    bad_text.append((a, v))
                else:
                    bad_structural.append((a, v, tagname, body[:50]))

print("Non-div4 STRUCTURAL coords (rect/line/circle):", len(bad_structural))
for b in bad_structural:
    print(b)
print()
print("Non-div4 TEXT baseline coords (exempt per template precedent, -6/+10 offset pattern):", len(bad_text))
EOF
